    "ps5_login_fail" to ("Účet na PS5 je chráněný přihlašovacím kódem. Zadej ho na stránce PlayStation." to "Účet na PS5 je chránený prihlasovacím kódom. Zadaj ho na stránke PlayStation."),
    "wz_ps5" to ("Aplikace se připojí k PlayStationu po domácí síti a čte z něj titulky. Hra běží dál kabelem HDMI v plné kvalitě. Spárování se dělá jen jednou." to "Aplikácia sa pripojí k PlayStationu po domácej sieti a číta z neho titulky. Hra beží ďalej káblom HDMI v plnej kvalite. Spárovanie sa robí len raz."),
    "err_video" to ("Toto zařízení neumí dekódovat video z PlayStationu." to "Toto zariadenie nevie dekódovať video z PlayStationu."),
    "help_1" to ("1. PlayStation nech připojený k televizi kabelem HDMI jako obvykle (plná kvalita)." to "1. PlayStation nechaj pripojený k televízoru káblom HDMI ako obvykle (plná kvalita)."),
    "help_2" to ("2. Na stránce PlayStation jednou spáruj konzoli – průvodce tě povede krok za krokem (k přihlášení účtu si vezmi telefon)." to "2. Na stránke PlayStation raz spáruj konzolu – sprievodca ťa povedie krok za krokom (na prihlásenie účtu si vezmi telefón)."),
    "help_4" to ("4. Na stránce Domů spusť překlad a počkej na „Připojeno“." to "4. Na stránke Domov spusti preklad a počkaj na „Pripojené“."),
    "help_5" to ("5. Přepni televizi na HDMI s PlayStationem a hraj." to "5. Prepni televízor na HDMI s PlayStationom a hraj."),
    "help_t1" to ("PlayStation připoj k routeru kabelem, nebo ho měj blízko Wi-Fi – čtení titulků bude rychlejší." to "PlayStation pripoj k routeru káblom, alebo ho maj blízko Wi-Fi – čítanie titulkov bude rýchlejšie."),
    "pa_1_title" to ("Vezmi si telefon a naskenuj čtvereček" to "Vezmi si telefón a naskenuj štvorček"),
    "pa_1_text" to ("PlayStation potřebuje vědět, ke kterému účtu se televize připojuje. Zjistí se to přihlášením k účtu PlayStation. Dělá se to v telefonu, jen jednou, a trvá to asi dvě minuty.\n\nOtevři v telefonu fotoaparát, namiř ho na čtvereček vlevo a klepni na odkaz, který se objeví. Pak tady zvol Pokračovat." to "PlayStation potrebuje vedieť, ku ktorému účtu sa televízor pripája. Zistí sa to prihlásením k účtu PlayStation. Robí sa to v telefóne, len raz, a trvá to asi dve minúty.\n\nOtvor v telefóne fotoaparát, namier ho na štvorček vľavo a ťukni na odkaz, ktorý sa objaví. Potom tu zvoľ Pokračovať."),
    "pa_2_title" to ("V telefonu se přihlas" to "V telefóne sa prihlás"),
    "acc2" to ("Důležité: v aplikaci se přihlas DRUHÝM účtem PlayStation, ne tím, na kterém hraješ. Kdyby se aplikace připojila tvým herním účtem, konzole by ti při hraní vypínala ovladač a zhasínala obraz.\n\nDruhý účet je zdarma: na PlayStationu zvol Přidat uživatele a založ nový účet s jiným e-mailem. Hrát budeš dál na svém účtu a se svými hrami – druhý účet se jen „dívá“." to "Dôležité: v aplikácii sa prihlás DRUHÝM účtom PlayStation, nie tým, na ktorom hráš. Keby sa aplikácia pripojila tvojím herným účtom, konzola by ti pri hraní vypínala ovládač a zhasínala obraz.\n\nDruhý účet je zadarmo: na PlayStatione zvoľ Pridať používateľa a založ nový účet s iným e-mailom. Hrať budeš ďalej na svojom účte a so svojimi hrami – druhý účet sa len „pozerá“."),
    "pa_2_text" to ("1. Zadej e-mail a heslo DRUHÉHO účtu PlayStation (ne toho, na kterém hraješ).\n2. Když se stránka zeptá na „passkey“, zvol Remind Me Later.\n3. Nakonec zůstane skoro prázdná stránka s jediným slovem „redirect“. Tak je to správně – nezavírej ji a tady zvol Pokračovat." to "1. Zadaj e-mail a heslo DRUHÉHO účtu PlayStation (nie toho, na ktorom hráš).\n2. Keď sa stránka opýta na „passkey“, zvoľ Remind Me Later.\n3. Nakoniec zostane takmer prázdna stránka s jediným slovom „redirect“. Tak je to správne – nezatváraj ju a tu zvoľ Pokračovať."),
    "pa_3_title" to ("Opiš kód z telefonu" to "Opíš kód z telefónu"),
    "pa_3_text" to ("V telefonu klepni nahoře na adresu té prázdné stránky. Je dlouhá – najdi v ní „code=“. Kód je to, co následuje hned za ním, až po znak &. Opiš ho do políčka přesně, i s tečkou a velkými písmeny, a zvol Ověřit kód. Kód platí jen pár minut." to "V telefóne ťukni hore na adresu tej prázdnej stránky. Je dlhá – nájdi v nej „code=“. Kód je to, čo nasleduje hneď za ním, až po znak &. Opíš ho do políčka presne, aj s bodkou a veľkými písmenami, a zvoľ Overiť kód. Kód platí len pár minút."),
    "pa_example" to ("Příklad adresy (tvůj kód bude jiný):" to "Príklad adresy (tvoj kód bude iný):"),
    "s_quality" to ("Přesnost čtení titulků" to "Presnosť čítania titulkov"),
    "net_cable" to ("Síť televize: kabel ✔" to "Sieť televízora: kábel ✔"),
    "net_wifi5" to ("Síť televize: Wi-Fi 5 GHz. Kdyby spojení vypadávalo, připoj PlayStation k routeru kabelem." to "Sieť televízora: Wi-Fi 5 GHz. Ak by spojenie vypadávalo, pripoj PlayStation k routeru káblom."),
    "net_wifi24" to ("Síť televize: Wi-Fi 2,4 GHz ⚠ Ve stejném pásmu vysílají ovladače konzole, proto aplikace bere menší obraz. Připoj PlayStation nebo televizi kabelem, nebo přepni Wi-Fi na 5 GHz." to "Sieť televízora: Wi-Fi 2,4 GHz ⚠ V rovnakom pásme vysielajú ovládače konzoly, preto aplikácia berie menší obraz. Pripoj PlayStation alebo televízor káblom, alebo prepni Wi-Fi na 5 GHz."),
    "q_auto" to ("Automaticky podle televize" to "Automaticky podľa televízora"),
    "q_std" to ("Standardní (šetří Wi-Fi a výkon)" to "Štandardná (šetrí Wi-Fi a výkon)"),
