    "pg_need_acc" to ("Nejdřív se přihlas účtem PlayStation." to "Najprv sa prihlás účtom PlayStation."),
    "ps5_acc_done" to ("Účet je ověřený ✔" to "Účet je overený ✔"),
    "ps5_acc_again" to ("Přihlásit se znovu nebo jiným účtem" to "Prihlásiť sa znova alebo iným účtom"),
    "pg_step" to ("Spárování – krok %d ze 4" to "Spárovanie – krok %d zo 4"),
    "pg_1_title" to ("Zapni na PlayStationu Remote Play" to "Zapni na PlayStatione Remote Play"),
    "pg_1_text" to ("Nejdřív se na PlayStationu přihlas na druhý účet – ten, na kterém nehraješ a který bude sloužit jen této aplikaci. Na PlayStationu otevři Nastavení → Systém → Remote Play a zapni „Povolit Remote Play“. Televize a PlayStation musí být ve stejné domácí síti (stejná Wi-Fi, nebo kabel do stejného routeru). Až to budeš mít, zvol Pokračovat.\n\nNejlépe to funguje, když jsou PlayStation i televize připojené k routeru kabelem (LAN). Přes Wi-Fi to jde také, ale překlad může být pomalejší." to "Najprv sa na PlayStatione prihlás na druhý účet – ten, na ktorom nehráš a ktorý bude slúžiť len tejto aplikácii. Na PlayStatione otvor Nastavenia → Systém → Remote Play a zapni „Povoliť Remote Play“. Televízor a PlayStation musia byť v rovnakej domácej sieti (rovnaká Wi-Fi alebo kábel do rovnakého routera). Keď to budeš mať, zvoľ Pokračovať.\n\nNajlepšie to funguje, keď sú PlayStation aj televízor pripojené k routeru káblom (LAN). Cez Wi-Fi to ide tiež, ale preklad môže byť pomalší."),
    "pg_2_title" to ("Najdi PlayStation" to "Nájdi PlayStation"),
    "pg_2_text" to ("Aplikace hledá tvůj PlayStation v domácí síti – musí být zapnutý. Když ho najde, adresa se vyplní sama. Když ne, najdeš ji na PlayStationu: Nastavení → Síť → Stav připojení → Adresa IPv4." to "Aplikácia hľadá tvoj PlayStation v domácej sieti – musí byť zapnutý. Keď ho nájde, adresa sa vyplní sama. Keď nie, nájdeš ju na PlayStatione: Nastavenia → Sieť → Stav pripojenia → Adresa IPv4."),
    "pg_4_title" to ("Opiš číslo z PlayStationu" to "Opíš číslo z PlayStationu"),
    "pg_4_text" to ("Nejdřív se na PlayStationu přepni na druhého uživatele – toho, kterým ses přihlásil v aplikaci. Na PlayStationu zvol Nastavení → Systém → Remote Play → Propojit zařízení. Ukáže se osmimístné číslo – opiš ho sem a zvol Spárovat. Číslo platí jen pár minut. Potom se na ovladači přepni zpět na svůj herní účet." to "Najprv sa na PlayStatione prepni na druhého používateľa – toho, ktorým si sa prihlásil v aplikácii. Na PlayStatione zvoľ Nastavenia → Systém → Remote Play → Prepojiť zariadenie. Ukáže sa osemmiestne číslo – opíš ho sem a zvoľ Spárovať. Číslo platí len pár minút. Potom sa na ovládači prepni späť na svoj herný účet."),
    "ps5_acc_ok" to ("Účet ověřen ✔ Teď zadej číslo z PS5 a zvol Spárovat." to "Účet overený ✔ Teraz zadaj číslo z PS5 a zvoľ Spárovať."),
    "ps5_acc_wait" to ("Ověřuji účet…" to "Overujem účet…"),
)

