        "pg_need_acc" to "Najpierw zaloguj się kontem PlayStation.",
        "ps5_acc_done" to "Konto potwierdzone ✔",
        "ps5_acc_again" to "Zaloguj się ponownie lub innym kontem",
        "pg_step" to "Parowanie – krok %d z 4",
        "pg_1_title" to "Włącz Granie zdalne na PlayStation",
        "pg_1_text" to "Najpierw zaloguj się na PlayStation na drugie konto – to, na którym nie grasz i które będzie służyć tylko tej aplikacji. Na PlayStation otwórz Ustawienia → System → Granie zdalne i włącz „Włącz Granie zdalne”. Telewizor i PlayStation muszą być w tej samej sieci domowej (to samo Wi-Fi albo kabel do tego samego routera). Gdy to zrobisz, wybierz Dalej.\n\nNajlepiej działa, gdy PlayStation i telewizor są podłączone do routera kablem (LAN). Przez Wi-Fi też się da, ale tłumaczenie może być wolniejsze.",
        "pg_2_title" to "Znajdź PlayStation",
        "pg_2_text" to "Aplikacja szuka PlayStation w sieci domowej – konsola musi być włączona. Gdy ją znajdzie, adres wypełni się sam. Jeśli nie, znajdziesz go na PlayStation: Ustawienia → Sieć → Stan połączenia → Adres IPv4.",
        "pg_4_title" to "Przepisz numer z PlayStation",
        "pg_4_text" to "Najpierw przełącz się na PlayStation na drugiego użytkownika – tego, którym zalogowałeś się w aplikacji. Na PlayStation wybierz Ustawienia → System → Granie zdalne → Połącz urządzenie. Pojawi się ośmiocyfrowy numer – wpisz go tutaj i wybierz Sparuj. Numer jest ważny tylko kilka minut. Potem na kontrolerze wróć na swoje konto do gry.",
        "ps5_acc_ok" to "Konto potwierdzone ✔ Teraz wpisz numer z PS5 i wybierz Sparuj.",
        "ps5_acc_wait" to "Sprawdzam konto…",
    ),
