        "ps5_forget" to "Скасувати пару",
        "ps5_preview" to "Що застосунок зараз бачить із PlayStation",
        "ps5_login_fail" to "Обліковий запис на PS5 захищено кодом входу. Введи його на сторінці PlayStation.",
        "wz_ps5" to "Застосунок підключається до PlayStation домашньою мережею і читає з неї субтитри. Гра й далі йде кабелем HDMI у повній якості. Пару створюють лише один раз.",
        "err_video" to "Цей пристрій не вміє декодувати відео з PlayStation.",
        "help_1" to "1. Залиш PlayStation підключеною до телевізора кабелем HDMI, як завжди (повна якість).",
        "help_2" to "2. На сторінці PlayStation один раз створи пару з консоллю – майстер проведе крок за кроком (для входу в обліковий запис візьми телефон).",
        "help_4" to "4. На головній сторінці запусти переклад і дочекайся «Підключено».",
        "help_5" to "5. Перемкни телевізор на HDMI з PlayStation і грай.",
        "help_t1" to "Підключи PlayStation до роутера кабелем або тримай її ближче до Wi-Fi – субтитри читатимуться швидше.",
        "pa_1_title" to "Візьми телефон і відскануй квадрат",
        "pa_1_text" to "PlayStation має знати, з яким обліковим записом підключається телевізор. Це з'ясовується входом в обліковий запис PlayStation. Робиться це на телефоні, лише один раз, і займає близько двох хвилин.\n\nВідкрий на телефоні камеру, наведи її на квадрат ліворуч і торкнися посилання, яке з'явиться. Потім вибери тут «Далі».",
        "pa_2_title" to "Увійди на телефоні",
        "acc2" to "Важливо: у застосунку увійди ДРУГИМ обліковим записом PlayStation, а не тим, на якому граєш. Якби застосунок під’єднався твоїм ігровим записом, консоль під час гри вимикала б твій контролер і гасила зображення.\n\nДругий обліковий запис безкоштовний: на PlayStation вибери «Додати користувача» і створи новий запис з іншою адресою e-mail. Грати ти й далі будеш на своєму записі зі своїми іграми – другий лише «дивиться».",
        "pa_2_text" to "1. Введи e-mail і пароль ДРУГОГО облікового запису PlayStation (не того, на якому граєш).\n2. Якщо сторінка запропонує «passkey», вибери Remind Me Later.\n3. Наприкінці залишиться майже порожня сторінка з одним словом «redirect». Так і має бути – не закривай її й вибери тут «Далі».",
        "pa_3_title" to "Введи код із телефона",
        "pa_3_text" to "На телефоні торкнися вгорі адреси тієї порожньої сторінки. Вона довга – знайди в ній «code=». Код – це те, що йде одразу після нього, до знака &. Введи його в поле точно, з крапкою й великими літерами, і вибери «Перевірити код». Код дійсний лише кілька хвилин.",
        "pa_example" to "Приклад адреси (твій код буде інший):",
        "s_quality" to "Точність читання субтитрів",
        "net_cable" to "Мережа телевізора: кабель ✔",
        "net_wifi5" to "Мережа телевізора: Wi-Fi 5 ГГц. Якщо з’єднання обриватиметься, під’єднай PlayStation до роутера кабелем.",
        "net_wifi24" to "Мережа телевізора: Wi-Fi 2,4 ГГц ⚠ У цьому ж діапазоні працюють контролери консолі, тому застосунок бере менше зображення. Під’єднай PlayStation або телевізор кабелем чи перемкни Wi-Fi на 5 ГГц.",
        "q_auto" to "Автоматично за телевізором",
        "q_std" to "Стандартна (економить Wi-Fi і ресурси)",
        "q_high" to "Висока (і дрібні субтитри)",
        "q_desc" to "Висока точність бере з PlayStation чіткішу копію зображення, тож читає й дрібні субтитри. Якщо переклад запізнюється або зникає, спробуй Стандартну.",
        "q_restart" to "Змінено – запусти переклад знову.",
        "ph_code" to "Код з адреси в телефоні (те, що після «code=»)",
        "ph_check" to "Перевірити код",
        "ph_bad" to "Код недійсний або вже прострочений. Увійди на телефоні ще раз і введи новий код.",
        "pg_need_acc" to "Спочатку увійди з обліковим записом PlayStation.",
        "ps5_acc_done" to "Обліковий запис підтверджено ✔",
        "ps5_acc_again" to "Увійти знову або з іншим обліковим записом",
        "pg_step" to "Створення пари – крок %d із 4",
        "pg_1_title" to "Увімкни дистанційну гру на PlayStation",
        "pg_1_text" to "Спочатку увійди на PlayStation у другий обліковий запис – той, на якому ти не граєш і який служитиме лише цьому застосунку. На PlayStation відкрий Налаштування → Система → Дистанційна гра й увімкни «Увімкнути дистанційну гру». Телевізор і PlayStation мають бути в одній домашній мережі (той самий Wi-Fi або кабель до того самого роутера). Коли зробиш, вибери «Далі».\n\nНайкраще працює, коли і PlayStation, і телевізор під’єднані до роутера кабелем (LAN). Через Wi-Fi теж можна, але переклад може бути повільнішим.",
        "pg_2_title" to "Знайди PlayStation",
        "pg_2_text" to "Застосунок шукає твою PlayStation у домашній мережі – вона має бути ввімкнена. Якщо знайде, адреса заповниться сама. Якщо ні, знайдеш її на PlayStation: Налаштування → Мережа → Стан підключення → Адреса IPv4.",
        "pg_4_title" to "Введи число з PlayStation",
        "pg_4_text" to "Спочатку перемкнися на PlayStation на другого користувача – того, яким ти увійшов у застосунку. На PlayStation вибери Налаштування → Система → Дистанційна гра → Підключити пристрій. З'явиться восьмизначне число – введи його тут і вибери «Створити пару». Число дійсне лише кілька хвилин. Потім на контролері повернися до свого ігрового запису.",
        "ps5_acc_ok" to "Обліковий запис підтверджено ✔ Тепер введи число з PS5 і вибери «Створити пару».",
        "ps5_acc_wait" to "Перевіряю обліковий запис…",
    ),
    Lang.ES to mapOf(
        "m_ps5" to "PlayStation",
        "st_ready_sub" to "Inicia la traducción y cambia el televisor al HDMI de la PlayStation.",
        "st_running_sub" to "Conectado a la PlayStation. Cambia el televisor al HDMI de la PlayStation y juega: los subtítulos aparecerán solos.",
        "st_connecting" to "Conectando con la PlayStation…",
        "st_waiting" to "La PlayStation no responde, lo intento de nuevo…",
        "st_unstable" to "La conexión con la PlayStation se cortó varias veces, así que la aplicación dejó de intentarlo (reconectar una y otra vez molesta al mando de la consola). Revisa el Wi-Fi del televisor y vuelve a iniciar la traducción.",
        "st_failed" to "No se puede conectar con la PlayStation. ¿Está encendida y en la misma red doméstica que el televisor?",
        "st_demo" to "Prueba con el ejemplo en marcha, sin PlayStation.",
        "st_nops5" to "Primero vincula la PlayStation (solo una vez).",
        "b_demo" to "Prueba sin PlayStation",
        "chk_ps5" to "PlayStation vinculada",
        "tip_ps5" to "El juego llega al televisor por el cable HDMI con calidad completa. La aplicación solo toma de la PlayStation, por la red, una copia de la imagen para leer los subtítulos: no necesitas nada más.",
        "ps5_paired" to "Vinculada",
        "ps5_find" to "Buscar la PlayStation en la red",
        "ps5_finding" to "Buscando la PlayStation…",
        "ps5_found" to "Encontrada:",
        "ps5_notfound" to "No he encontrado la PlayStation en la red. Escribe su dirección a mano (en la PS5: Ajustes → Red → Estado de conexión → Dirección IPv4).",
        "ps5_ip" to "Dirección de la PlayStation (p. ej. 192.168.1.20)",
        "ps5_pin" to "Número de la PS5 (8 cifras)",
        "ps5_login" to "Código de inicio de sesión de la PS5, solo si lo tienes (4 cifras)",
        "ps5_pair" to "Vincular",
        "ps5_pairing" to "Vinculando con la PlayStation…",
        "ps5_ok" to "Listo, la PlayStation está vinculada. Ahora inicia sesión en el mando con la cuenta con la que juegas e inicia la traducción.",
        "ps5_fail" to "No se pudo vincular. Comprueba el número de la PS5 (solo vale unos minutos), la dirección y la cuenta, e inténtalo de nuevo.",
        "ps5_bad_ip" to "La dirección de la PlayStation no parece correcta.",
        "ps5_bad_pin" to "El número de la PS5 debe tener 8 cifras.",
